import 'package:flutter/material.dart';import '../navigation/top_navigation.dart';import 'introduction_page.dart';import 'civilization_page.dart';import 'human_profile_page.dart';class WorldShell extends StatefulWidget{const WorldShell({super.key});@override State<WorldShell>createState()=>_WorldShellState();}class _WorldShellState extends State<WorldShell>{TopDestination d=TopDestination.introduction;@override Widget build(BuildContext c){final page=switch(d){TopDestination.introduction=>const IntroductionPage(),TopDestination.workers=>const CivilizationPage(),TopDestination.humans=>const HumanProfilePage()};return Scaffold(body:Row(children:[TopNavigation(selected:d,onSelected:(v)=>setState(()=>d=v)),Expanded(child:page)]));}}
